/// url = 'https://icr.healthcampaigns.org/StructureMap/StageDIGITBoundaryTree'
/// name = 'StageDIGITBoundaryTree'
/// status = 'draft'

// Every boundary code of a DIGIT boundary tree as a staged Basic, for the
// StgBoundary view: a facility's partOf is its locality boundary only when
// that boundary was exported. Staged resources are not written to the output.
uses "https://icr.healthcampaigns.org/StructureDefinition/DIGITBoundaryTree" alias DIGITBoundaryTree as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/StructureDefinition/Basic" alias Basic as target

group StageBoundaryTree(source src : DIGITBoundaryTree, target bundle : Bundle) {
  src -> bundle.type = 'collection' "bundleType";
  src.boundary as b then StageBoundary(b, bundle) "top";
}

// Boundary `b`, then its children: the group calls itself.
group StageBoundary(source b, target bundle : Bundle) {
  b.code as c -> bundle.entry as e, e.resource = create('Basic') as basic, basic.code as k, k.text = 'digit-boundary', basic.identifier as i, i.value = c "boundary";
  b.children as c then StageBoundary(c, bundle) "children";
}
